#nullable enable // autogenerated

using MVZ2.Vanilla.Level;
using PVZEngine.Buffs;
using PVZEngine.Definitions;
using PVZEngine.Modifiers;

namespace MVZ2.GameContent.Buffs.Level
{
    [AutoBuffDefinition(VanillaBuffNames.Level.raining)]
    public class RainingBuff : BuffDefinition
    {
        public RainingBuff(string nsp, string name) : base(nsp, name)
        {
            AddModifier(new BooleanModifier(VanillaLevelProps.RAINING, true));
        }
    }
}
